// LoadRoutines loads the exercise's Routines into the .R struct
func (os ExerciseSlice) LoadRoutines(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	q := os.Routines(append(
		mods,
		// since we are changing the columns, the defaults must be added if the
		// original mods did not set any; this runs after the user mods and
		// before the related_* columns below, so it sees exactly what they set
		bob.ModFunc[*dialect.SelectQuery](func(q *dialect.SelectQuery) {
			if len(q.SelectList.Columns) == 0 {
				sm.Columns(Routines.Columns).Apply(q)
			}
		}),
		sm.Columns(ExercisesRoutines.Columns.ExerciseID.As("related_exercises.ID")),
	)...)

	IDSlice := make([]uuid.UUID, 0, len(os))

	mapper := scan.Mod(q.Scanner, func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any, any) error) {
		// Resolve each joined key column name to its index once per query. The
		// previous code scanned by name on every row, which meant a linear column
		// search per row; the columns are added by this loader so they are always
		// present, but an unselected column simply stays unresolved and is skipped.
		IDIdx := -1
		for i, col := range cols {
			switch col {
			case "related_exercises.ID":
				IDIdx = i
			}
		}

		return func(row *scan.Row) (any, error) {
				IDSlice = append(IDSlice, *new(uuid.UUID))
				if IDIdx >= 0 {
					row.ScheduleScanByIndex(IDIdx, &IDSlice[len(IDSlice)-1])
				}

				return nil, nil
			},
			func(any, any) error {
				return nil
			}
	})

	routines, err := bob.Allx[bob.SliceTransformer[*Routine, RoutineSlice]](ctx, exec, q, mapper)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}
		o.R.Routines = nil
		o.R.Loaded.Routines = true
	}
	// O(N+M) stitch via a map; child key is the carried slice IDSlice[i] (was O(N*M)).
	exerciseByKey := make(map[uuid.UUID][]*Exercise, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		exerciseByKey[o.ID] = append(exerciseByKey[o.ID], o)
	}

	for i, rel := range routines {
		owners, ok := exerciseByKey[IDSlice[i]]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.Exercises = append(rel.R.Exercises, o)

			o.R.Routines = append(o.R.Routines, rel)

		}
	}

	return nil
}

