type exerciseJoins[Q dialect.Joinable] struct {
	typ               string
	User              modAs[Q, userColumns]
	ExercisesRoutines modAs[Q, exercisesRoutineColumns]
	Routines          modAs[Q, routineColumns]
	Sets              modAs[Q, setColumns]
}

func (j exerciseJoins[Q]) aliasedAs(alias string) exerciseJoins[Q] {
	return buildExerciseJoins[Q](buildExerciseColumns(alias), j.typ)
}

func buildExerciseJoins[Q dialect.Joinable](cols exerciseColumns, typ string) exerciseJoins[Q] {
	return exerciseJoins[Q]{
		typ: typ,
		User: modAs[Q, userColumns]{
			c: Users.Columns,
			f: func(to userColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Users.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.UserID),
					))
				}

				return mods
			},
		},
		ExercisesRoutines: modAs[Q, exercisesRoutineColumns]{
			c: ExercisesRoutines.Columns,
			f: func(to exercisesRoutineColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, ExercisesRoutines.NameExpr().As(to.Alias())).On(
						to.ExerciseID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		Routines: modAs[Q, routineColumns]{
			c: Routines.Columns,
			f: func(to routineColumns) bob.Mod[Q] {
				uniqueSuffix := strconv.FormatUint(bob.NextUniqueInt(), 10)
				mods := make(mods.QueryMods[Q], 0, 2)

				{
					to := ExercisesRoutines.Columns.AliasedAs(ExercisesRoutines.Columns.Alias() + uniqueSuffix)
					mods = append(mods, dialect.Join[Q](typ, ExercisesRoutines.NameExpr().As(to.Alias())).On(
						to.ExerciseID.EQ(cols.ID),
					))
				}
				{
					cols := ExercisesRoutines.Columns.AliasedAs(ExercisesRoutines.Columns.Alias() + uniqueSuffix)
					mods = append(mods, dialect.Join[Q](typ, Routines.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.RoutineID),
					))
				}

				return mods
			},
		},
		Sets: modAs[Q, setColumns]{
			c: Sets.Columns,
			f: func(to setColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Sets.NameExpr().As(to.Alias())).On(
						to.ExerciseID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
